//! The AMX instruction set: opcode numbers, mnemonics and operand encoding.
//!
//! GENERATED by `scripts/genopcodes.mjs` from the AMX Mod X compiler's
//! `libpc300/sc6.c` `opcodelist[]` table - do not edit by hand.
//!
//! The numbers here are a binary format: the assembler writes them straight into
//! the `.amx` code segment, so a wrong value produces a plugin that misbehaves at
//! runtime rather than failing to compile. `sc6.c` is the authoritative source in
//! this tree; the copy of `amx.h` shipped with `libpc300` declares only the runtime
//! structures and does not contain the `OP_*` enum.
//!
//! Operand counts come from the emit function each row is bound to in `sc6.c`:
//! `parm0` writes the opcode alone, `parm1` writes one operand cell, `parm2` two,
//! and `do_call` / `do_jump` / `do_switch` each write one operand cell holding a
//! resolved code address (`lbltab[i]`). `casetbl` is declared `parm0` but is
//! followed by a variable-length table written by `do_case` - see [`Operands`].

/// How many cell-sized operands follow an opcode in the code segment.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Operands {
    /// No operands: the instruction is a single cell (sc6.c `parm0`).
    None,
    /// One operand cell (sc6.c `parm1`, `do_call`, `do_jump`, `do_switch`).
    One,
    /// Two operand cells (sc6.c `parm2`; debug records only).
    Two,
    /// [`Opcode::Casetbl`]: the opcode is followed by `2 + 2 * n` cells. sc6.c emits
    /// these as `case` rows through `do_case`, which writes two cells and *no*
    /// opcode. The first pair is `(n, default_address)`, the remaining `n` pairs are
    /// `(match_value, code_address)`. Every address in the table needs relocation.
    CaseTable,
    /// Variable length, encoded by the instruction itself (sc6.c `do_file` /
    /// `do_symbol`: a size cell followed by an inline string). Never emitted by
    /// this compiler - both rows are commented out of `opcodelist`.
    Variable,
}

impl Operands {
    /// The number of operand cells, when it is fixed. `None` for the
    /// variable-length forms, whose size can only be known from the bytecode.
    pub fn count(self) -> Option<u32> {
        match self {
            Operands::None => Some(0),
            Operands::One => Some(1),
            Operands::Two => Some(2),
            Operands::CaseTable | Operands::Variable => Option::None,
        }
    }
}

/// An AMX instruction. Discriminants are the on-disk opcode numbers.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum Opcode {
    /// Not an instruction. sc6.c reserves entry 0 of `opcodelist` as the
    /// "invalid instruction" node; the mnemonic `none` is our own placeholder so that
    /// every variant round-trips through [`Opcode::mnemonic`].
    None = 0,
    /// PRI = [address]
    LoadPri = 1,
    /// ALT = [address]
    LoadAlt = 2,
    /// PRI = [FRM + offset]
    LoadSPri = 3,
    /// ALT = [FRM + offset]
    LoadSAlt = 4,
    /// PRI = [[address]]
    LrefPri = 5,
    /// ALT = [[address]]
    LrefAlt = 6,
    /// PRI = [[FRM + offset]]
    LrefSPri = 7,
    /// ALT = [[FRM + offset]]
    LrefSAlt = 8,
    /// PRI = [PRI]
    LoadI = 9,
    /// PRI = "number" bytes from [PRI] (partial cell load)
    LodbI = 10,
    /// PRI = value
    ConstPri = 11,
    /// ALT = value
    ConstAlt = 12,
    /// PRI = FRM + offset
    AddrPri = 13,
    /// ALT = FRM + offset
    AddrAlt = 14,
    /// [address] = PRI
    StorPri = 15,
    /// [address] = ALT
    StorAlt = 16,
    StorSPri = 17,
    StorSAlt = 18,
    SrefPri = 19,
    SrefAlt = 20,
    SrefSPri = 21,
    SrefSAlt = 22,
    /// [ALT] = PRI
    StorI = 23,
    /// store "number" bytes of PRI at [ALT]
    StrbI = 24,
    /// PRI = [ALT + (PRI x cell size)]
    Lidx = 25,
    /// PRI = [ALT + (PRI << shift)]
    LidxB = 26,
    /// PRI = ALT + (PRI x cell size)
    Idxaddr = 27,
    /// PRI = ALT + (PRI << shift)
    IdxaddrB = 28,
    /// align PRI for a packed-string access of "number" bytes
    AlignPri = 29,
    AlignAlt = 30,
    /// PRI = special register (COD/DAT/HEA/STP/STK/FRM/CIP)
    Lctrl = 31,
    /// special register = PRI
    Sctrl = 32,
    MovePri = 33,
    MoveAlt = 34,
    Xchg = 35,
    PushPri = 36,
    PushAlt = 37,
    /// push a reference: the value at [value] relative to DAT, "value" times
    PushR = 38,
    PushC = 39,
    Push = 40,
    PushS = 41,
    PopPri = 42,
    PopAlt = 43,
    /// ALT = STK, STK = STK + value (adjust the stack)
    Stack = 44,
    /// ALT = HEA, HEA = HEA + value (allocate on the heap)
    Heap = 45,
    /// function prologue: push FRM, FRM = STK
    Proc = 46,
    /// function epilogue without stack cleanup
    Ret = 47,
    /// function epilogue: pop FRM and the argument count
    Retn = 48,
    /// call a function; the operand is a code address
    Call = 49,
    CallPri = 50,
    /// unconditional jump; the operand is a code address
    Jump = 51,
    /// jump relative to the current CIP by a plain number (not a label)
    Jrel = 52,
    Jzer = 53,
    Jnz = 54,
    Jeq = 55,
    Jneq = 56,
    Jless = 57,
    Jleq = 58,
    Jgrtr = 59,
    Jgeq = 60,
    Jsless = 61,
    Jsleq = 62,
    Jsgrtr = 63,
    Jsgeq = 64,
    Shl = 65,
    Shr = 66,
    Sshr = 67,
    ShlCPri = 68,
    ShlCAlt = 69,
    ShrCPri = 70,
    ShrCAlt = 71,
    Smul = 72,
    Sdiv = 73,
    SdivAlt = 74,
    Umul = 75,
    Udiv = 76,
    UdivAlt = 77,
    Add = 78,
    Sub = 79,
    SubAlt = 80,
    And = 81,
    Or = 82,
    Xor = 83,
    Not = 84,
    Neg = 85,
    Invert = 86,
    AddC = 87,
    SmulC = 88,
    ZeroPri = 89,
    ZeroAlt = 90,
    Zero = 91,
    ZeroS = 92,
    SignPri = 93,
    SignAlt = 94,
    Eq = 95,
    Neq = 96,
    Less = 97,
    Leq = 98,
    Grtr = 99,
    Geq = 100,
    Sless = 101,
    Sleq = 102,
    Sgrtr = 103,
    Sgeq = 104,
    EqCPri = 105,
    EqCAlt = 106,
    IncPri = 107,
    IncAlt = 108,
    Inc = 109,
    IncS = 110,
    IncI = 111,
    DecPri = 112,
    DecAlt = 113,
    Dec = 114,
    DecS = 115,
    DecI = 116,
    Movs = 117,
    Cmps = 118,
    Fill = 119,
    /// abort execution with the given exit code
    Halt = 120,
    /// abort with an array-bounds error if PRI > value
    Bounds = 121,
    /// call the native function whose index is in PRI
    SysreqPri = 122,
    /// call the native function with the given index (arguments already pushed)
    SysreqC = 123,
    /// Debug record: source file name. Variable length (the string follows).
    /// Commented out of sc6.c's table - never emitted by this compiler.
    File = 124,
    /// Debug record: line number. Commented out of sc6.c's table.
    Line = 125,
    /// Debug record: symbol name. Variable length. Commented out of sc6.c's table.
    Symbol = 126,
    /// Debug record: symbol range. Commented out of sc6.c's table.
    Srange = 127,
    /// jump to the code address in PRI
    JumpPri = 128,
    /// switch: the operand is the code address of the following CASETBL
    Switch = 129,
    /// case table header; followed by a variable-length list of (value, address) pairs
    Casetbl = 130,
    SwapPri = 131,
    SwapAlt = 132,
    /// push the address of a local (FRM + offset)
    Pushaddr = 133,
    /// no operation (padding)
    Nop = 134,
    /// call a native by its direct address; not generated by this compiler
    SysreqD = 135,
    /// Debug record: symbol tag. Commented out of sc6.c's table.
    Symtag = 136,
    /// debugger breakpoint
    Break = 137,
}

